package com.amit.jobagent.application;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;
@Entity @Table(name="generated_claim")class GeneratedClaim{@Id UUID id;@Column(name="generated_content_id",nullable=false,updatable=false)UUID contentId;@Column(name="claim_text",nullable=false,length=2000)String text;@Enumerated(EnumType.STRING)@Column(name="claim_type",nullable=false,length=40)ClaimType type;@Column(name="content_path",nullable=false,length=300)String path;@Enumerated(EnumType.STRING)@Column(name="validation_status",nullable=false,length=30)ClaimValidationStatus validation;@JdbcTypeCode(SqlTypes.JSON)@Column(name="validation_codes",columnDefinition="jsonb",nullable=false)String codes;@Column(name="created_at",nullable=false,updatable=false)Instant createdAt;protected GeneratedClaim(){}GeneratedClaim(UUID content,String text,ClaimType type,String path,ClaimValidationStatus validation,String codes){id=UUID.randomUUID();contentId=content;this.text=text;this.type=type;this.path=path;this.validation=validation;this.codes=codes;createdAt=Instant.now();}void requireReviewAfterUserEdit(){validation=ClaimValidationStatus.REQUIRES_REVIEW;codes="[\"USER_EDITED_CONTENT\"]";}}
